initialSelectedPageId.content:
let page = 'actionsList';
switch (Context.interfaceState.state.selectedPanel) {
	case 'actions': page = 'actionsList'; break;
	case 'radios': page = 'radioMainPanel'; break;
	case 'notification': page = '64'; break;
	case 'resources': page = 'locationBase'; break;
	default: page = 'actionsList';
}
page;

